<?php
session_start();if(empty($_SESSION['user_id'])){header('Location:/pages/login.php');exit;}if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location:/pages/cart.php');exit;}require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/promotions.php';require_once __DIR__.'/../config/order_reservations.php';require_once __DIR__.'/../config/order_notifications.php';$userId=(int)$_SESSION['user_id'];
$ids=$_SESSION['checkout_selected_ids']??[];$name=trim((string)($_POST['shipping_name']??''));$address=trim((string)($_POST['shipping_address']??''));$phone=trim((string)($_POST['shipping_phone']??''));if(!$ids||$name===''||$address===''||$phone===''){header('Location:/pages/checkout_summary.php');exit;}
$marks=implode(',',array_fill(0,count($ids),'?'));$stmt=$pdo->prepare("SELECT ci.quantity,b.book_id,b.title,b.category,b.price,b.stock_quantity,b.seller_type,b.seller_id FROM cart_items ci JOIN books b ON b.book_id=ci.book_id WHERE ci.user_id=? AND ci.book_id IN ($marks) AND b.status='available' FOR UPDATE");
$pdo->beginTransaction();try{$stmt->execute(array_merge([$userId],$ids));$items=$stmt->fetchAll(PDO::FETCH_ASSOC);if(!$items)throw new RuntimeException('ไม่พบสินค้าในตะกร้า');$groups=[];foreach($items as $item){if((int)$item['quantity']>(int)$item['stock_quantity'])throw new RuntimeException('สินค้า '.$item['title'].' มีจำนวนไม่เพียงพอ');$groups[$item['seller_type'].'-'.$item['seller_id']][]=$item;}
$insertOrder=$pdo->prepare("INSERT INTO orders(user_id,order_number,subtotal,shipping_fee,promotion_id,promotion_name,discount_amount,reservation_expires_at,stock_reserved,total_amount,shipping_name,shipping_address,shipping_phone,shipping_method,payment_status,shipping_status) VALUES(?,?,?,?,?,?,?,?,1,?,?,?,?,?,'pending','pending')");$insertItem=$pdo->prepare('INSERT INTO order_items(order_id,book_id,quantity,price_at_purchase) VALUES(?,?,?,?)');$insertAppliedPromotion=$pdo->prepare('INSERT INTO order_applied_promotions(order_id,promotion_id,promotion_name,discount_amount) VALUES(?,?,?,?)');$reserveStock=$pdo->prepare('UPDATE books SET stock_quantity=stock_quantity-? WHERE book_id=? AND stock_quantity>=?');$reservationExpiresAt=date('Y-m-d H:i:s',time()+86400);$orderIds=[];$index=0;
foreach($groups as $group){$index++;$subtotal=array_sum(array_map(fn($i)=>(float)$i['price']*(int)$i['quantity'],$group));$quantity=array_sum(array_map(fn($i)=>(int)$i['quantity'],$group));$shipping=wanawanShippingFee($quantity);$promotion=wanawanBestSellerPromotion($pdo,$group[0]['seller_type'],(int)$group[0]['seller_id'],$subtotal,$quantity,$group);$total=$subtotal+$shipping-$promotion['discount_amount'];$number='WN'.date('YmdHis').str_pad((string)$index,2,'0',STR_PAD_LEFT).random_int(10,99);$insertOrder->execute([$userId,$number,$subtotal,$shipping,$promotion['promotion_id'],$promotion['promotion_name'],$promotion['discount_amount'],$reservationExpiresAt,$total,$name,$address,$phone,'PromptPay']);$orderId=(int)$pdo->lastInsertId();$orderIds[]=$orderId;foreach($promotion['applied_promotions'] as $applied)$insertAppliedPromotion->execute([$orderId,$applied['promotion_id'],$applied['promotion_name'],$applied['discount_amount']]);foreach($group as $item){$reserveStock->execute([(int)$item['quantity'],(int)$item['book_id'],(int)$item['quantity']]);if($reserveStock->rowCount()!==1)throw new RuntimeException('สินค้า '.$item['title'].' มีจำนวนไม่เพียงพอ');$insertItem->execute([$orderId,$item['book_id'],$item['quantity'],$item['price']]);/* หนังสือมือ 2 ที่ user โพสต์ขาย: เปลี่ยนสถานะเป็น sold เมื่อสต็อกหมด */if(($item['seller_type']??'')==='user'){$checkStock=$pdo->prepare('SELECT stock_quantity,book_type FROM books WHERE book_id=?');$checkStock->execute([(int)$item['book_id']]);$bookRow=$checkStock->fetch(PDO::FETCH_ASSOC);if($bookRow&&(int)$bookRow['stock_quantity']<=0&&$bookRow['book_type']==='used'){$markSold=$pdo->prepare("UPDATE books SET status='sold' WHERE book_id=? AND stock_quantity<=0");$markSold->execute([(int)$item['book_id']]);}}}}

$pdo->commit();$newOrder=$pdo->prepare('SELECT order_id,user_id,order_number FROM orders WHERE order_id=?');foreach($orderIds as $createdId){$newOrder->execute([$createdId]);if($created=$newOrder->fetch(PDO::FETCH_ASSOC))wanawanNotifyOrderBuyer($pdo,$created,'สร้างคำสั่งซื้อเรียบร้อยแล้ว','สินค้าถูกสำรองไว้ 24 ชั่วโมง กรุณาชำระเงินภายในเวลาที่กำหนด');}$_SESSION['checkout_batch_order_ids']=$orderIds;unset($_SESSION['checkout_selected_ids']);header('Location:/pages/payment_batch.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['checkout_error']=$e->getMessage();header('Location:/pages/checkout_summary.php');exit;}
